"use client"

import * as React from "react"

// The chart's shared state: its config, its id (which scopes the fill patterns) and the defaults that give every
// series a colour and a fill. Series differ by fill (flat, stipple, louvers, tint) as well as by colour, so a chart
// still reads in grey, in print and where two chart colours are the same spot.

// Format: { THEME_NAME: CSS_SELECTOR }. Night is a colourway (data-colourway="night" on <html> or any ancestor).
export const THEMES = { light: "", dark: '[data-colourway="night"]' } as const

/**
 * How a series fills its bars, areas and slices: the flat spot colour, the colour under a fine ink stipple, the colour
 * in louvers (slats of colour and ink, like a stair seen from below), or a tint of the colour toward paper.
 */
export type ChartFill = "flat" | "stipple" | "louvers" | "tint"

/** Series without a fill take the next one in this order. */
export const CHART_FILLS: readonly ChartFill[] = [
  "flat",
  "stipple",
  "louvers",
  "tint",
]

export type ChartConfig = Record<
  string,
  {
    label?: React.ReactNode
    icon?: React.ComponentType
    /** Serigraph: how the series fills its marks; defaults by position in the config. */
    fill?: ChartFill
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
>

type ChartContextProps = {
  config: ChartConfig
  /** Scopes the chart's fill patterns, so several charts on a page never share an id. */
  chartId: string
}

export const ChartContext = React.createContext<ChartContextProps | null>(null)

export function useChart() {
  const context = React.useContext(ChartContext)

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />")
  }

  return context
}

const position = (config: ChartConfig, key: string | undefined) =>
  key ? Math.max(0, Object.keys(config).indexOf(key)) : 0

/** A series' fill, explicit or by its position in the config. */
export function seriesFill(
  config: ChartConfig,
  key: string | undefined,
): ChartFill {
  const own = key ? config[key]?.fill : undefined
  return own ?? CHART_FILLS[position(config, key) % CHART_FILLS.length]!
}

/** A series' colour in a theme: its own, else the chart colour for its position (--chart-1 … --chart-5). */
export function seriesColor(
  config: ChartConfig,
  key: string,
  theme: keyof typeof THEMES = "light",
) {
  const item = config[key]
  return (
    item?.theme?.[theme] ??
    item?.color ??
    `var(--chart-${(position(config, key) % 5) + 1})`
  )
}

/** The id of a series' fill pattern (stipple, louvers) inside one chart. */
export function fillId(chartId: string, key: string) {
  return `${chartId}-fill-${key.replace(/[^\w-]/g, "_")}`
}

/** What a fill paints a shape with: the series' colour, its pattern, or its tint. */
export function fillPaint(chartId: string, key: string, fill: ChartFill) {
  if (fill === "flat") return `var(--color-${key})`
  if (fill === "tint")
    return `color-mix(in oklab, var(--color-${key}) 38%, var(--paper))`
  return `url(#${fillId(chartId, key)})`
}

/** A line's dash for a fill: stipple series draw dotted lines, louvers dashed, tint long and short; flat a full line. */
export function fillDash(fill: ChartFill) {
  if (fill === "stipple") return "0.01 5"
  if (fill === "louvers") return "7 4"
  if (fill === "tint") return "12 4 2 4"
  return undefined
}

/**
 * The paint for a series' bars, areas and slices, for `<Bar fill={chartFill("shows")} />`. Marks filled with
 * `var(--color-<key>)` take the same paint anyway; this is for code that wants to say so.
 */
export const chartFill = (key: string) => `var(--fill-${key})`

/** A series' flat colour, for strokes, dots and labels. */
export const chartColor = (key: string) => `var(--color-${key})`

/**
 * The config key an item belongs to: the value of `key` on the item or its data row (a pie slice's name, say),
 * else `key` itself. Undefined when neither is in the config.
 */
export function getPayloadConfigKey(
  config: ChartConfig,
  payload: unknown,
  key: string,
): string | undefined {
  if (typeof payload !== "object" || payload === null) {
    return undefined
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined

  let configLabelKey: string = key

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string
  }

  if (configLabelKey in config) return configLabelKey
  return key in config ? key : undefined
}

"use client"

import { cn } from "@/serigraph/lib/utils"
import {
  fillDash,
  fillId,
  seriesFill,
  useChart,
  type ChartConfig,
  type ChartFill,
} from "@/serigraph/ui/chart-context"

// The fills that tell series apart besides colour: a fine ink stipple and louvers (slats of colour and ink), as SVG
// patterns defined once per chart over the series' own colour. The same tiles as the style's motifs (styles/
// surfaces.css): the stipple's staggered dots and the progress bar's 3 + 2 px slats, in user space, so neighbouring
// bars share one grid.

function FillPattern({
  id,
  fill,
  color,
}: {
  id: string
  fill: ChartFill
  color: string
}) {
  if (fill === "louvers") {
    return (
      <pattern id={id} width={6} height={5} patternUnits="userSpaceOnUse">
        <rect width={6} height={5} fill={color} />
        <rect y={3} width={6} height={2} fill="var(--ink)" />
      </pattern>
    )
  }
  return (
    <pattern id={id} width={4} height={4} patternUnits="userSpaceOnUse">
      <rect width={4} height={4} fill={color} />
      <circle cx={1} cy={1} r={0.7} fill="var(--ink)" />
      <circle cx={3} cy={3} r={0.7} fill="var(--ink)" />
    </pattern>
  )
}

/** The stipple and louver series' patterns for one chart, in a hidden SVG that the chart's shapes refer to by id. */
export function ChartFillDefs({
  chartId,
  config,
}: {
  chartId: string
  config: ChartConfig
}) {
  const patterned = Object.keys(config).filter((key) => {
    const fill = seriesFill(config, key)
    return fill === "stipple" || fill === "louvers"
  })
  if (!patterned.length) return null
  return (
    <svg
      aria-hidden="true"
      focusable="false"
      width="0"
      height="0"
      className="pointer-events-none absolute"
    >
      <defs>
        {patterned.map((key) => (
          <FillPattern
            key={key}
            id={fillId(chartId, key)}
            fill={seriesFill(config, key)}
            color={`var(--color-${key})`}
          />
        ))}
      </defs>
    </svg>
  )
}

/**
 * A series' key in a tooltip or legend: a small square in its fill inside the ink line, or for a line a short stroke
 * in its dash through a bead in its colour.
 */
export function ChartSwatch({
  seriesKey,
  variant = "fill",
  className,
}: {
  seriesKey?: string
  variant?: "fill" | "line"
  className?: string
}) {
  const { config } = useChart()
  const color = seriesKey ? `var(--color-${seriesKey})` : "var(--paper)"

  if (variant === "line") {
    return (
      <svg
        data-slot="chart-swatch"
        aria-hidden="true"
        viewBox="0 0 20 10"
        className={cn("h-2.5 w-5 shrink-0 overflow-visible", className)}
      >
        <line
          x1={1}
          y1={5}
          x2={19}
          y2={5}
          stroke="currentColor"
          strokeLinecap="round"
          strokeDasharray={fillDash(seriesFill(config, seriesKey))}
          style={{ strokeWidth: "calc(var(--line) * 1.5)" }}
        />
        <circle
          cx={10}
          cy={5}
          r={3.25}
          fill={color}
          stroke="var(--ink)"
          style={{ strokeWidth: "var(--line)" }}
        />
      </svg>
    )
  }

  return (
    <svg
      data-slot="chart-swatch"
      aria-hidden="true"
      viewBox="0 0 12 12"
      className={cn("size-3 shrink-0 overflow-visible", className)}
    >
      <rect
        x={0.75}
        y={0.75}
        width={10.5}
        height={10.5}
        rx={2}
        fill={seriesKey ? `var(--fill-${seriesKey})` : color}
        stroke="var(--ink)"
        style={{ strokeWidth: "var(--line)" }}
      />
    </svg>
  )
}

"use client"

import * as React from "react"
import * as RechartsPrimitive from "recharts"
import type { TooltipValueType } from "recharts"
import { cn } from "@/serigraph/lib/utils"
import { getPayloadConfigKey, useChart } from "@/serigraph/ui/chart-context"
import { ChartSwatch } from "@/serigraph/ui/chart-marks"

// The tooltip is a small floating plane in the ink line, like a popover: the label in the extended capitals, one row
// per series with its swatch, its name in the reading face and its value in the mono face. The legend is a row of
// names on the chart's surface, each with its swatch (a stroke and a bead for a line).

type TooltipNameType = number | string

const figure = (value: unknown) =>
  typeof value === "number" ? value.toLocaleString("en-GB") : String(value)

function ChartTooltipContent({
  active,
  payload,
  className,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  label,
  labelFormatter,
  labelClassName,
  formatter,
  nameKey,
  labelKey,
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
  React.ComponentProps<"div"> & {
    hideLabel?: boolean
    hideIndicator?: boolean
    indicator?: "line" | "dot" | "dashed"
    nameKey?: string
    labelKey?: string
  } & Omit<
    RechartsPrimitive.DefaultTooltipContentProps<
      TooltipValueType,
      TooltipNameType
    >,
    "accessibilityLayer"
  >) {
  const { config } = useChart()

  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) {
      return null
    }

    const [item] = payload
    const key = `${labelKey ?? item?.dataKey ?? item?.name ?? "value"}`
    const configKey = getPayloadConfigKey(config, item, key)
    const value =
      !labelKey && typeof label === "string"
        ? (config[label]?.label ?? label)
        : configKey && config[configKey]?.label

    const classes = cn("caps", labelClassName)
    if (labelFormatter) {
      return <div className={classes}>{labelFormatter(value, payload)}</div>
    }

    if (!value) {
      return null
    }

    return <div className={classes}>{value}</div>
  }, [
    label,
    labelFormatter,
    payload,
    hideLabel,
    labelClassName,
    config,
    labelKey,
  ])

  if (!active || !payload?.length) {
    return null
  }

  return (
    <div
      data-slot="chart-tooltip"
      className={cn(
        "float-plane grid min-w-40 items-start gap-hair px-snug py-tight font-read text-small leading-small",
        className,
      )}
    >
      {tooltipLabel}
      <div className="grid gap-1">
        {payload
          .filter((item) => item.type !== "none")
          .map((item, index) => {
            const key = `${nameKey ?? item.name ?? item.dataKey ?? "value"}`
            const configKey = getPayloadConfigKey(config, item, key)
            const itemConfig = configKey ? config[configKey] : undefined

            return (
              <div
                key={index}
                className="flex w-full items-center gap-tight [&>svg:not([data-slot=chart-swatch])]:size-3"
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <ChartSwatch
                          seriesKey={configKey}
                          variant={indicator === "dot" ? "fill" : "line"}
                        />
                      )
                    )}
                    <div className="flex flex-1 items-baseline justify-between gap-snug">
                      <span>{itemConfig?.label ?? item.name}</span>
                      {item.value != null && (
                        <span className="font-mono tabular-nums">
                          {figure(item.value)}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            )
          })}
      </div>
    </div>
  )
}

// Areas report a "line" legend type too; a line is a "line" item whose series fills nothing (Recharts gives lines #fff).
const isLine = (item: { type?: string; payload?: unknown }) => {
  const fill = (item.payload as { fill?: unknown } | undefined)?.fill
  return (
    item.type === "line" &&
    (typeof fill !== "string" || fill === "#fff" || fill === "none")
  )
}

function ChartLegendContent({
  className,
  hideIcon = false,
  payload,
  verticalAlign = "bottom",
  nameKey,
}: React.ComponentProps<"div"> & {
  hideIcon?: boolean
  nameKey?: string
} & RechartsPrimitive.DefaultLegendContentProps) {
  const { config } = useChart()

  if (!payload?.length) {
    return null
  }

  const keys = Object.keys(config)
  const order = (key?: string) => {
    const at = key ? keys.indexOf(key) : -1
    return at < 0 ? keys.length : at
  }

  return (
    <div
      data-slot="chart-legend"
      className={cn(
        "flex flex-wrap items-center justify-center gap-x-snug gap-y-hair font-read text-small leading-small",
        verticalAlign === "top" ? "pb-tight" : "pt-tight",
        className,
      )}
    >
      {payload
        .filter((item) => item.type !== "none")
        .map((item) => {
          const key = `${nameKey ?? item.dataKey ?? "value"}`
          return { item, configKey: getPayloadConfigKey(config, item, key) }
        })
        // In config order, the order fills are dealt in, not Recharts' alphabetical one.
        .sort((a, b) => order(a.configKey) - order(b.configKey))
        .map(({ item, configKey }, index) => {
          const itemConfig = configKey ? config[configKey] : undefined
          return (
            <div
              key={index}
              className="flex items-center gap-1.5 [&>svg:not([data-slot=chart-swatch])]:size-3"
            >
              {itemConfig?.icon && !hideIcon ? (
                <itemConfig.icon />
              ) : (
                <ChartSwatch
                  seriesKey={configKey}
                  variant={isLine(item) ? "line" : "fill"}
                />
              )}
              {itemConfig?.label ?? item.value}
            </div>
          )
        })}
    </div>
  )
}

export { ChartTooltipContent, ChartLegendContent }

"use client"

import * as React from "react"
import * as RechartsPrimitive from "recharts"
import { cn } from "@/serigraph/lib/utils"
import {
  ChartContext,
  THEMES,
  fillDash,
  fillPaint,
  seriesColor,
  seriesFill,
  type ChartConfig,
} from "@/serigraph/ui/chart-context"
import { ChartFillDefs } from "@/serigraph/ui/chart-marks"

// Recharts printed like the poster: every bar, area and slice is a flat shape inside the ink line, and series are
// told apart by fill (flat, stipple, louvers, tint) as well as by colour (--chart-1 … --chart-5). Lines are the fine
// line itself, dashed by their fill, with beads in the series' colour. Axis figures in the mono face, the grid rows
// of fine dots, the tooltip a floating plane. The drawing classes cannot reach is in styles/data.css; the per-series
// rules are written by ChartStyle, so shadcn's own `fill="var(--color-<key>)"` takes the series' fill unchanged.

const INITIAL_DIMENSION = { width: 320, height: 200 } as const

function ChartContainer({
  id,
  className,
  children,
  config,
  initialDimension = INITIAL_DIMENSION,
  ...props
}: React.ComponentProps<"div"> & {
  config: ChartConfig
  children: React.ComponentProps<
    typeof RechartsPrimitive.ResponsiveContainer
  >["children"]
  initialDimension?: {
    width: number
    height: number
  }
}) {
  const uniqueId = React.useId()
  const chartId = `chart-${(id ?? uniqueId).replace(/[^\w-]/g, "")}`
  const context = React.useMemo(() => ({ config, chartId }), [config, chartId])

  return (
    <ChartContext.Provider value={context}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cn(
          "relative flex aspect-video justify-center font-mono text-small leading-small text-(--text)",
          className,
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <ChartFillDefs chartId={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer
          initialDimension={initialDimension}
        >
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  )
}

const quoted = (value: string) => `"${value.replace(/["\\]/g, "\\$&")}"`

/**
 * Writes --color-<key> (the series' colour, per theme) and --fill-<key> (its paint: the colour, its pattern or its
 * tint) for every series, and the rules that hand a series' fill to the shapes Recharts fills with its colour: bars,
 * areas and slices take the fill, lines their dash, line points the colour.
 */
const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const keys = Object.keys(config)
  if (!keys.length) return null

  const chart = `[data-chart=${quoted(id)}]`
  const blocks = Object.entries(THEMES).map(([theme, prefix]) => {
    const night = theme !== "light"
    const lines = keys.flatMap((key) => {
      const item = config[key]
      if (night && !item?.theme) return []
      return [
        `  --color-${key}: ${seriesColor(config, key, theme as keyof typeof THEMES)};`,
        night
          ? null
          : `  --fill-${key}: ${fillPaint(id, key, seriesFill(config, key))};`,
      ].filter((line) => line !== null)
    })
    return lines.length
      ? `${prefix} ${chart} {\n${lines.join("\n")}\n}`.trim()
      : ""
  })

  const rules = keys.map((key) => {
    const color = quoted(`var(--color-${key})`)
    const dash = fillDash(seriesFill(config, key))
    return [
      `${chart} :is(.recharts-rectangle, .recharts-sector, .recharts-area-area)[fill=${color}] { fill: var(--fill-${key}); }`,
      `${chart} .recharts-dot[stroke=${color}] { fill: var(--color-${key}); }`,
      dash
        ? `${chart} .recharts-line-curve[stroke=${color}] { stroke-dasharray: ${dash}; }`
        : "",
    ].join("\n")
  })

  const css = [...blocks, ...rules].filter(Boolean).join("\n")
  return <style dangerouslySetInnerHTML={{ __html: css }} />
}

/** Recharts' tooltip, which follows the pointer at once: its default 400 ms glide makes hovering feel slow. */
function ChartTooltip(
  props: React.ComponentProps<typeof RechartsPrimitive.Tooltip>,
) {
  return <RechartsPrimitive.Tooltip isAnimationActive={false} {...props} />
}

const ChartLegend = RechartsPrimitive.Legend

export { ChartContainer, ChartTooltip, ChartLegend, ChartStyle }
export {
  ChartTooltipContent,
  ChartLegendContent,
} from "@/serigraph/ui/chart-tooltip"
export { ChartSwatch } from "@/serigraph/ui/chart-marks"
export {
  CHART_FILLS,
  chartColor,
  chartFill,
  type ChartConfig,
  type ChartFill,
} from "@/serigraph/ui/chart-context"
